const state={loadToken:0,testInspectionId:null,inspectionId:null,selectedTest:null,preparedId:null,prepared:null,runId:null,timer:null,liveSpec:null,liveCandidates:[],selectedCandidateId:null,browsePath:null,parameterConfig:{},parameterForest:[],parameterOpen:new Set(),edaSetup:null,pendingConfig:null,pendingCheckpoint:null,rangeValidationJobId:null,rangeValidationTimer:null,rangeValidationResults:{},rangeValidationRequested:{}};
const $=id=>document.getElementById(id);
const palette=['#668fc4','#6cae9b','#c58aa0','#9b8ec4','#d5a25f','#6fa6b4','#9cab67','#c47b6d','#7f91aa','#b18a68'];

async function api(path,options={}){const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const data=await response.json();if(!response.ok)throw new Error(data.error||response.statusText);return data}
function esc(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function number(value,digits=6){const parsed=Number(value);if(!Number.isFinite(parsed))return '-';if(parsed===0)return '0';const absolute=Math.abs(parsed);return absolute>=1e5||absolute<1e-3?parsed.toExponential(Math.max(2,digits-1)):parsed.toPrecision(digits)}
const algorithmNames={nsga2:'NSGA-II',differential_evolution:'Differential Evolution',bayesian_optimization:'Bayesian Optimization'};
const algorithmDescriptions={nsga2:'Multi-objective elitist evolution with simulated-binary crossover and polynomial mutation.',differential_evolution:'Single-objective differential evolution with target-versus-trial replacement.',bayesian_optimization:'Single-objective deterministic kernel surrogate with exploration-aware batch acquisition.'};
const algorithmInputMaps={nsga2:{population:'nsgaPopulation',seed:'nsgaSeed',crossover_probability:'nsgaCrossoverProbability',crossover_eta:'nsgaCrossoverEta',mutation_probability:'nsgaMutationProbability',mutation_eta:'nsgaMutationEta'},differential_evolution:{population:'dePopulation',seed:'deSeed',differential_weight:'deDifferentialWeight',crossover_rate:'deCrossoverRate'},bayesian_optimization:{population:'bayesPopulation',seed:'bayesSeed',initial_samples:'bayesInitialSamples',acquisition_exploration:'bayesExploration',candidate_pool:'bayesCandidatePool',noise:'bayesNoise',kernel_length_scale:'bayesKernelLengthScale',max_observations:'bayesMaxObservations'}};
function selectedParameterCount(){return Math.max(1,Object.values(state.parameterConfig).filter(config=>config.selected).length)}
function automaticPopulation(count){return Math.max(20,Math.min(100,Math.round(5*Math.sqrt(count))))}
function calculatedAlgorithmDefaults(algorithm,count=selectedParameterCount()){const population=automaticPopulation(count);if(algorithm==='nsga2')return {population,seed:1,crossover_probability:.9,crossover_eta:Number((15+Math.sqrt(count)).toFixed(3)),mutation_probability:1/count,mutation_eta:Number((20+.5*Math.sqrt(count)).toFixed(3))};if(algorithm==='differential_evolution')return {population,seed:1,differential_weight:Number(Math.max(.5,.9-.005*count).toFixed(3)),crossover_rate:Number(Math.min(.95,.7+.005*count).toFixed(3))};return {population,seed:1,initial_samples:Math.max(population,2*count+1),acquisition_exploration:Number(Math.max(1,2.5-.02*count).toFixed(3)),candidate_pool:Math.max(200,10*count),noise:1e-6,kernel_length_scale:Number(Math.max(.08,1/Math.sqrt(count)).toFixed(6)),max_observations:Math.max(80,2*count+1)}}
function updateAlgorithmDefaults(force=false){Object.entries(algorithmInputMaps).forEach(([algorithm,map])=>{const defaults=calculatedAlgorithmDefaults(algorithm);Object.entries(map).forEach(([key,id])=>{const input=$(id);if(force||input.dataset.manual!=='true'){input.value=defaults[key];input.dataset.manual='false'}})});renderAlgorithmSettings()}
function renderAlgorithmSettings(){const algorithm=$('algorithm').value;document.querySelectorAll('[data-algorithm-panel]').forEach(panel=>panel.hidden=panel.dataset.algorithmPanel!==algorithm);$('algorithmDescription').textContent=algorithmDescriptions[algorithm];const objectives=document.querySelectorAll('.objective').length;const incompatible=objectives>1&&algorithm!=='nsga2';$('algorithmWarning').innerHTML=incompatible?'<span class="bad">Differential Evolution and Bayesian Optimization support one objective only. Select NSGA-II or remove extra objectives.</span>':algorithm==='nsga2'?'Supports single- and multi-objective optimization.':'Single-objective algorithm.';$('algorithmSummary').textContent=`${algorithmNames[algorithm]} · ${$(algorithmInputMaps[algorithm].population).value||'-'} individuals`}
function applyAlgorithmSettings(algorithm,parameters={}){$('algorithm').value=algorithmNames[algorithm]?algorithm:'nsga2';updateAlgorithmDefaults(false);const map=algorithmInputMaps[$('algorithm').value];Object.entries(parameters||{}).forEach(([key,value])=>{const input=$(map[key]);if(input&&value!=null){input.value=value;input.dataset.manual='true'}});renderAlgorithmSettings()}
function collectAlgorithmSettings(){const algorithm=$('algorithm').value;const parameters={};Object.entries(algorithmInputMaps[algorithm]).forEach(([key,id])=>{const input=$(id);const value=Number(input.value);if(!Number.isFinite(value))throw new Error(`${input.closest('label').childNodes[0].textContent.trim()} must be numeric.`);parameters[key]=value});for(const key of ['population','seed','initial_samples','candidate_pool','max_observations'])if(key in parameters&&!Number.isInteger(parameters[key]))throw new Error(`${key} must be an integer.`);if(document.querySelectorAll('.objective').length>1&&algorithm!=='nsga2')throw new Error(`${algorithmNames[algorithm]} supports one objective only; use NSGA-II for multi-objective optimization.`);return {algorithm,algorithm_parameters:parameters}}
function downloadJson(name,value){const blob=new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function readJsonFile(input){const file=input.files?.[0];if(!file)throw new Error('Choose a JSON file.');if(file.size>64*1024*1024)throw new Error('File exceeds the 64 MiB checkpoint limit.');try{return JSON.parse(await file.text())}catch(error){throw new Error(`Invalid JSON file: ${error.message}`)}finally{input.value=''}}
const physicalScales={t:1e12,g:1e9,meg:1e6,k:1e3,m:1e-3,u:1e-6,n:1e-9,p:1e-12,f:1e-15,a:1e-18};
function physicalUnit(parameter){const raw=String(parameter.current_value??parameter.default_value??'').trim().replace(/^"|"$/g,'');const match=raw.match(/[a-zA-Z]+$/);return match&&physicalScales[match[0].toLowerCase()]?match[0]:''}
function parsePhysicalInput(value,fallbackUnit=''){const text=String(value??'').trim();const match=text.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)([a-zA-Z]+)?$/);if(!match)return NaN;const unit=match[2]||fallbackUnit;const scale=unit?physicalScales[unit.toLowerCase()]:1;return scale?Number(match[1])*scale:NaN}
function formatPhysical(value,unit=''){const numeric=Number(value);if(!Number.isFinite(numeric))return '';const scale=unit?physicalScales[unit.toLowerCase()]:1;return String(Number((numeric/scale).toPrecision(8)))}
function boundDefault(parameter,side,unit){const value=Number(parameter.numeric_value);if(!Number.isFinite(value))return '';const integer=parameter.value_type==='integer';const defined=side==='min'?parameter.minimum:parameter.maximum;if(defined!=null&&defined!==''){const parsed=parsePhysicalInput(defined,unit);if(Number.isFinite(parsed))return integer?String(Math.round(parsed)):formatPhysical(parsed,unit)}let bound;if(integer){const center=Math.round(value);bound=side==='min'?Math.max(1,Math.floor(center*.5)):Math.max(2,Math.ceil(center*2.5));if(side==='max')bound=Math.max(bound,Math.max(1,Math.floor(center*.5))+1)}else if(value>0)bound=side==='min'?value*.5:value*2.5;else if(value<0)bound=side==='min'?value*2.5:value*.5;else bound=side==='min'?0:1;return integer?String(bound):formatPhysical(bound,unit)}

const edaFieldMap={cadence_root:'edaCadenceRoot',spectre_root:'edaSpectreRoot',virtuoso_bin:'edaVirtuosoBin',ocean_bin:'edaOceanBin',spectre_bin:'edaSpectreBin',cds_lib:'edaCdsLib',license_file:'edaLicense',pdk_name:'edaPdkName',pdk_dir:'edaPdkDir'};
function pathLines(value){return String(value||'').split(/\r?\n/).map(item=>item.trim()).filter(Boolean)}
function pdkPolicyOptionValue(value,legacyAdapter){const policy=typeof value==='string'?{mode:value}:value||{};if(policy.mode==='allow'){const ids=policy.adapter_ids||[policy.adapter_id];return ids[0]?`allow:${ids[0]}`:'auto'}if(['auto','generic-only','custom'].includes(policy.mode))return policy.mode;if(legacyAdapter&&legacyAdapter!=='generic-cdf')return 'custom';return 'auto'}
function togglePdkCustomAdapter(){const custom=$('edaPdkPolicy').value==='custom';$('edaPdkAdapterLabel').hidden=!custom;$('edaPdkAdapter').disabled=!custom}
function renderPdkPolicyOptions(setup,effective){const options=setup.pdk_adapter_options||[];if(options.length)$('edaPdkPolicy').innerHTML=options.map(option=>`<option value="${esc(option.id)}" ${option.available===false?'disabled':''}>${esc(option.label)}${option.available===false?' (not installed)':''}</option>`).join('');const selected=pdkPolicyOptionValue(effective.pdk_adapter_policy,effective.pdk_adapter);if([...$('edaPdkPolicy').options].some(option=>option.value===selected&&!option.disabled))$('edaPdkPolicy').value=selected;else $('edaPdkPolicy').value=selected==='custom'?'custom':'auto';const policy=typeof effective.pdk_adapter_policy==='object'?effective.pdk_adapter_policy:{};$('edaPdkAdapter').value=policy.path||(effective.pdk_adapter&&effective.pdk_adapter!=='generic-cdf'?effective.pdk_adapter:'');$('edaPdkProfiles').value=(effective.pdk_profiles||[]).length?JSON.stringify(effective.pdk_profiles,null,2):'';togglePdkCustomAdapter()}
function renderEdaSetup(setup){state.edaSetup=setup;const effective=setup.effective||{};Object.entries(edaFieldMap).forEach(([key,id])=>$(id).value=effective[key]||'');renderPdkPolicyOptions(setup,effective);$('edaBinaryPaths').value=(effective.extra_binary_paths||[]).join('\n');$('edaLibraryPaths').value=(effective.extra_library_paths||[]).join('\n');const badge=$('edaSetupBadge');badge.textContent=setup.ok?`${setup.mode==='manual'?'Manual':'Auto'} · Ready`:`${setup.mode==='manual'?'Manual':'Auto'} · Needs attention`;badge.className=`setup-state ${setup.ok?'good':'bad'}`;const checks=(setup.checks||[]).map(check=>`<span class="eda-check ${check.ok?'good':'bad'}">${check.ok?'✓':'×'} ${esc(check.name)}</span>`).join('');const versions=(setup.version_checks||[]).map(check=>`<span class="eda-check ${check.ok?'good':'bad'}" title="${esc(check.version||check.message||'')}">${check.ok?'✓':'×'} ${esc(check.name)} version</span>`).join('');const recommendations=(setup.recommendations||[]).map(item=>`<li>${esc(item)}</li>`).join('');$('edaDiscoverySummary').innerHTML=`<div class="eda-checks">${checks}${versions}</div><div>User config: <span class="path">${esc(setup.user_config_path||'not saved')}</span></div>${recommendations?`<ul class="eda-recommendations">${recommendations}</ul>`:''}`}
async function loadEdaSetup(){try{renderEdaSetup(await api('/api/eda-setup'))}catch(error){$('edaSetupBadge').textContent='Detection failed';$('edaSetupBadge').className='setup-state bad';$('edaDiscoverySummary').innerHTML=`<span class="bad">${esc(error.message)}</span>`}}
function collectEdaOverrides(){const manual={};Object.entries(edaFieldMap).forEach(([key,id])=>{const value=$(id).value.trim();if(value)manual[key]=value});manual.extra_binary_paths=pathLines($('edaBinaryPaths').value);manual.extra_library_paths=pathLines($('edaLibraryPaths').value);manual.search_roots=state.edaSetup?.effective?.search_roots||[];manual.pdk_adapter='generic-cdf';const policy=$('edaPdkPolicy').value;if(policy==='custom'){const path=$('edaPdkAdapter').value.trim();if(!path)throw new Error('Custom Adapter SKILL path is required.');manual.pdk_adapter_policy={mode:'custom',path}}else manual.pdk_adapter_policy=policy;const profilesText=$('edaPdkProfiles').value.trim();if(profilesText){let profiles;try{profiles=JSON.parse(profilesText)}catch(error){throw new Error(`PDK Profiles JSON is invalid: ${error.message}`)}if(!Array.isArray(profiles))throw new Error('PDK Profiles JSON must be an array.');manual.pdk_profiles=profiles}else manual.pdk_profiles=[];return manual}
async function saveEdaSetup(){const button=$('saveEdaSetup');try{button.disabled=true;$('edaSetupMessage').textContent='Validating executables and compatibility...';const setup=await api('/api/eda-setup',{method:'POST',body:JSON.stringify({mode:'manual',manual:collectEdaOverrides()})});renderEdaSetup(setup);$('edaSetupMessage').innerHTML='<span class="good">Overrides validated and saved.</span>'}catch(error){$('edaSetupMessage').innerHTML=`<span class="bad">${esc(error.message)}</span>`}finally{button.disabled=false}}
async function resetEdaSetup(){const button=$('resetEdaSetup');try{button.disabled=true;$('edaSetupMessage').textContent='Running automatic discovery...';const setup=await api('/api/eda-setup',{method:'POST',body:JSON.stringify({mode:'auto'})});renderEdaSetup(setup);$('edaSetupMessage').innerHTML=setup.ok?'<span class="good">Automatic discovery restored.</span>':'<span class="bad">Automatic discovery is incomplete. Review the checks and recommendations.</span>'}catch(error){$('edaSetupMessage').innerHTML=`<span class="bad">${esc(error.message)}</span>`}finally{button.disabled=false}}
function renderPdkContext(context){const target=$('pdkContextSummary');if(!context){target.textContent='PDK context will be checked after loading the ADE setup.';return}const candidates=(context.candidate_libraries||[]).join(', ')||'none';const contexts=context.contexts||[];const rows=contexts.map(row=>{const adapter=row.adapter_selection||{};return `<div><b>${esc(row.name||row.id)}</b> · Libraries ${esc((row.reference_libraries||[]).join(', ')||'none')} · Adapter ${esc(adapter.label||adapter.adapter_id||'Generic CDF')} · ${esc(adapter.reason||'generic_first')}</div>`}).join('');if(context.blocking){target.innerHTML=`<span class="bad">PDK context is blocking.</span> ${esc((context.recommendations||[]).join(' '))}${rows}`;return}target.innerHTML=context.ok?`${contexts.length} PDK context${contexts.length===1?'':'s'} detected.${rows}`:`<span class="muted">No external PDK context was identified.</span> Candidate device libraries: ${esc(candidates)}. ${esc((context.recommendations||[]).join(' '))}`}

function buildParameterForest(){const catalog=new Map((state.prepared?.parameters||[]).filter(parameter=>parameter.optimizable).map(parameter=>[parameter.parameter_id,parameter]));return (state.prepared?.hierarchy?.designs||[]).map((design,designIndex)=>{const hierarchy=design.hierarchy||{};const cells=new Map((hierarchy.cells||[]).map(cell=>[cell.hierarchy_path,cell]));const rootCell=cells.get('/')||{};const root={id:`design-${designIndex}:/`,path:'/',name:rootCell.cell||design.design?.[1]||`Design ${designIndex+1}`,kind:'cell',library:rootCell.library||design.design?.[0]||'',masterCell:rootCell.cell||design.design?.[1]||'',depth:0,parameters:[],children:[]};const nodes=new Map([['/',root]]);(hierarchy.instances||[]).slice().sort((left,right)=>Number(left.depth)-Number(right.depth)).forEach(instance=>nodes.set(instance.hierarchy_path,{id:`design-${designIndex}:${instance.hierarchy_path}`,path:instance.hierarchy_path,name:instance.name,kind:instance.kind==='hierarchical'?'cell':'device',library:instance.master_library||'',masterCell:instance.master_cell||'',depth:Number(instance.depth)||0,parameters:[],children:[]}));(hierarchy.instances||[]).forEach(instance=>{const node=nodes.get(instance.hierarchy_path);const parent=nodes.get(instance.parent_path||'/');if(node&&parent)parent.children.push(node)});(hierarchy.parameters||[]).forEach(raw=>{const parameter=catalog.get(raw.parameter_id);const node=nodes.get(raw.hierarchy_path);if(parameter&&node&&!node.parameters.some(item=>item.parameter_id===parameter.parameter_id))node.parameters.push(parameter)});const prune=node=>{node.children=node.children.map(prune).filter(Boolean);node.parameters.sort((left,right)=>String(left.name).localeCompare(String(right.name)));node.children.sort((left,right)=>left.kind===right.kind?left.name.localeCompare(right.name):left.kind==='cell'?-1:1);return node.parameters.length||node.children.length?node:null};return prune(root)}).filter(Boolean)}
function subtreeParameters(node){return [...node.parameters,...node.children.flatMap(subtreeParameters)]}
function syncParameterInputs(){document.querySelectorAll('[data-parameter-id]').forEach(row=>{const config=state.parameterConfig[row.dataset.parameterId];if(!config)return;const minimum=row.querySelector('.var-min')?.value;const maximum=row.querySelector('.var-max')?.value;if(minimum!=null)config.minimum=minimum;if(maximum!=null)config.maximum=maximum;const scale=row.querySelector('.var-scale')?.value;if(scale)config.scale=scale})}
function filteredNode(node,query,ancestorMatched=false){const ownText=`${node.name} ${node.path} ${node.library} ${node.masterCell}`.toLowerCase();const ownMatch=ancestorMatched||!query||ownText.includes(query);const parameters=ownMatch?node.parameters:node.parameters.filter(parameter=>`${parameter.name} ${parameter.prompt||''} ${parameter.current_value}`.toLowerCase().includes(query));const children=node.children.map(child=>filteredNode(child,query,ownMatch)).filter(Boolean);return ownMatch||parameters.length||children.length?{...node,parameters,children}:null}
function rangeEndpointLabel(parameter,row){if(!row)return '<span class="pending">Not checked</span>';const endpoint=row.endpoint==='minimum'?'Min':'Max';if(row.status==='valid')return `<span class="range-valid">${endpoint} valid</span>`;if(row.status==='applied')return `<span class="range-applied">${endpoint} applied: ${esc(row.applied_from)} → ${esc(row.effective)}</span>`;if(row.status==='pdk_adjusted'){const unit=physicalUnit(parameter);const requested=unit?`${formatPhysical(row.requested,unit)}${unit}`:row.requested;return `<span class="range-adjusted" title="${esc(JSON.stringify(row.evidence||{}))}">${endpoint} PDK adjusted: ${esc(requested)} → ${esc(row.effective)}</span>`}return `<span class="range-invalid" title="${esc(row.error||'Validation failed')}">${endpoint} failed</span>`}
function rangeValidationCell(parameter){const rows=state.rangeValidationResults[parameter.parameter_id]||[];return `<div class="range-validation-cell">${rangeEndpointLabel(parameter,rows.find(row=>row.endpoint==='minimum'))}${rangeEndpointLabel(parameter,rows.find(row=>row.endpoint==='maximum'))}</div>`}
function adjustableRangeRows(){return Object.values(state.rangeValidationResults).flat().filter(row=>row.status==='pdk_adjusted')}
function updateRangeApplyButton(){const button=$('applyValidatedRangesButton');const count=adjustableRangeRows().length;button.hidden=count===0;button.disabled=count===0;button.textContent=count?`Apply ${count} Legal Range${count===1?'':'s'}`:'Apply Legal Ranges'}
function validatedBoundInput(parameter,row){const config=state.parameterConfig[parameter.parameter_id];const parsed=parsePhysicalInput(row.effective,'');if(!Number.isFinite(parsed))throw new Error(`PDK returned an invalid ${row.endpoint} value for ${parameter.name}.`);return config.value_type==='integer'?String(Math.round(parsed)):formatPhysical(parsed,config.unit)}
function applyValidatedRanges(){syncParameterInputs();const changes=[];adjustableRangeRows().forEach(row=>{const parameter=state.prepared.parameters.find(item=>item.parameter_id===row.parameter_id);const config=state.parameterConfig[row.parameter_id];if(!parameter||!config)return;const field=row.endpoint==='minimum'?'minimum':'maximum';const oldValue=config[field];const newValue=validatedBoundInput(parameter,row);config[field]=newValue;const tableRow=document.querySelector(`[data-parameter-id="${CSS.escape(row.parameter_id)}"]`);const input=tableRow?.querySelector(row.endpoint==='minimum'?'.var-min':'.var-max');if(input)input.value=newValue;row.status='applied';row.applied_from=`${oldValue}${config.unit||''}`;const path=parameter.hierarchy_path||parameter.instance_path||parameter.path||'';changes.push(`${path?`${path}/`:''}${parameter.name} ${row.endpoint}: ${oldValue}${config.unit||''} → ${newValue}${config.unit||''}`)});renderParameters();updateRangeApplyButton();$('rangeValidationSummary').innerHTML=`<span class="good">Applied ${changes.length} legal range adjustment${changes.length===1?'':'s'}.</span>${changes.length?`<ul class="range-change-list">${changes.map(change=>`<li>${esc(change)}</li>`).join('')}</ul>`:''}`}
function parameterRow(parameter){const config=state.parameterConfig[parameter.parameter_id];const unit=config.unit?`<span class="range-unit">${esc(config.unit)}</span>`:'';const integer=config.value_type==='integer';return `<tr data-parameter-id="${esc(parameter.parameter_id)}"><td><input class="var-select" type="checkbox" ${config.selected?'checked':''} aria-label="Select ${esc(parameter.name)}"></td><td><b>${esc(parameter.name)}</b><span class="semantic-tag">${esc(parameter.semantic||'value')}</span><br><span class="muted">${esc(parameter.prompt||parameter.cdf_type||'Numeric CDF')}</span></td><td>${esc(parameter.current_value)}</td><td><span class="range-field"><input class="var-min" type="text" inputmode="${integer?'numeric':'decimal'}" value="${esc(config.minimum)}">${unit}</span></td><td><span class="range-field"><input class="var-max" type="text" inputmode="${integer?'numeric':'decimal'}" value="${esc(config.maximum)}">${unit}</span></td><td><select class="var-scale" ${integer?'disabled':''}><option value="linear" ${config.scale==='linear'?'selected':''}>linear</option><option value="log" ${config.scale==='log'?'selected':''} ${Number(parameter.numeric_value)>0&&!integer?'':'disabled'}>log</option></select></td><td>${rangeValidationCell(parameter)}</td></tr>`}
function findTreeNode(nodes,id){for(const node of nodes){if(node.id===id)return node;const match=findTreeNode(node.children,id);if(match)return match}return null}
function renderTreeNode(node){const parameters=subtreeParameters(node);const selected=parameters.filter(parameter=>state.parameterConfig[parameter.parameter_id]?.selected).length;const open=state.parameterOpen.has(node.id);const icon=node.kind==='cell'?'▣':'◇';const label=node.kind==='cell'?(node.path==='/'?node.masterCell:`${node.name} · ${node.masterCell}`):`${node.name} · ${node.masterCell}`;const direct=node.parameters.length?`<div class="device-parameters"><table><thead><tr><th>Select</th><th>Parameter</th><th>Current</th><th>Minimum</th><th>Maximum</th><th>Scale</th><th>PDK Validation</th></tr></thead><tbody>${node.parameters.map(parameterRow).join('')}</tbody></table></div>`:'';return `<details class="tree-node tree-${node.kind}" data-node-id="${esc(node.id)}" ${open?'open':''}><summary><span class="tree-caret"></span><input class="tree-select" type="checkbox" data-node-select="${esc(node.id)}" ${selected===parameters.length?'checked':''}><span class="tree-icon">${icon}</span><span class="tree-label"><b>${esc(label)}</b><small>${esc(node.library)}/${esc(node.masterCell)} · <span class="path">${esc(node.path)}</span></small></span><span class="tree-count">${selected}/${parameters.length} selected</span></summary><div class="tree-content">${direct}${node.children.map(renderTreeNode).join('')}</div></details>`}
function updateSelectedParameterCount(){const count=Object.values(state.parameterConfig).filter(config=>config.selected).length;const target=$('selectedParameterCount');if(target)target.textContent=count;updateAlgorithmDefaults(false)}
function renderParameters(){syncParameterInputs();const query=$('parameterFilter').value.trim().toLowerCase();const forest=state.parameterForest.map(node=>filteredNode(node,query)).filter(Boolean);$('parameterTree').innerHTML=forest.length?forest.map(renderTreeNode).join(''):'<div class="empty-state compact-empty">No optimizable parameters match this filter.</div>';document.querySelectorAll('.tree-node').forEach(details=>{details.ontoggle=()=>{if(details.open)state.parameterOpen.add(details.dataset.nodeId);else state.parameterOpen.delete(details.dataset.nodeId)}});document.querySelectorAll('[data-node-select]').forEach(checkbox=>{const node=findTreeNode(state.parameterForest,checkbox.dataset.nodeSelect);if(!node)return;const parameters=subtreeParameters(node);const selected=parameters.filter(parameter=>state.parameterConfig[parameter.parameter_id]?.selected).length;checkbox.indeterminate=selected>0&&selected<parameters.length;checkbox.onclick=event=>{event.stopPropagation();parameters.forEach(parameter=>state.parameterConfig[parameter.parameter_id].selected=checkbox.checked);renderParameters()}});document.querySelectorAll('[data-parameter-id]').forEach(row=>{const config=state.parameterConfig[row.dataset.parameterId];row.querySelector('.var-select').onchange=event=>{config.selected=event.target.checked;renderParameters()};row.querySelectorAll('.var-min,.var-max').forEach(input=>input.onchange=()=>{syncParameterInputs();delete state.rangeValidationResults[row.dataset.parameterId];delete state.rangeValidationRequested[row.dataset.parameterId];renderParameters();updateRangeApplyButton()});row.querySelectorAll('.var-scale').forEach(input=>input.onchange=syncParameterInputs)});updateSelectedParameterCount()}
function setParameterTreeExpanded(expanded){const visit=node=>{if(expanded||node.path==='/')state.parameterOpen.add(node.id);else state.parameterOpen.delete(node.id);node.children.forEach(visit)};state.parameterForest.forEach(visit);renderParameters()}
function selectSemantic(semantic,selected){Object.entries(state.parameterConfig).forEach(([parameterId,config])=>{const parameter=state.prepared.parameters.find(item=>item.parameter_id===parameterId);if(parameter?.semantic===semantic)config.selected=selected});renderParameters()}
function flashSemanticButton(button){button.classList.remove('semantic-clicked');void button.offsetWidth;button.classList.add('semantic-clicked');setTimeout(()=>button.classList.remove('semantic-clicked'),420)}
function outputOptions(){return (state.prepared?.outputs||[]).map(output=>`<option value="${esc(output.key)}">${esc(output.key)}</option>`).join('')}
function cornerNames(){const setup=state.prepared?.setup||{};const mask=(setup.test_corner_masks||{})[setup.selected_test]||{};const rows=setup.corners?.length?setup.corners:[{name:'_default',enabled:true}];return rows.filter(row=>row.enabled!==false&&(row.name==='_default'?mask.nominal_enabled===true:mask.known===true&&!(mask.disabled_corners||[]).includes(row.name))).map(row=>row.name)}
function defaultCornerNames(){return cornerNames()}
function cornerPicker(){const corners=cornerNames();return `<details class="corner-picker"><summary>All corners (${corners.length})</summary><div class="corner-menu"><label class="corner-action"><input class="corner-all" type="checkbox" checked> Select all</label><label class="corner-action"><input class="corner-none" type="checkbox"> Select none</label><div class="corner-divider"></div>${corners.map(corner=>`<label><input class="corner-option" type="checkbox" value="${esc(corner)}" checked> ${esc(corner)}</label>`).join('')}<div class="corner-warning" hidden>Select at least one corner.</div></div></details>`}
function updateCornerPicker(row){const picker=row.querySelector('.corner-picker');const options=[...picker.querySelectorAll('.corner-option')];const selected=options.filter(option=>option.checked);picker.querySelector('summary').textContent=selected.length===options.length?`All corners (${options.length})`:selected.length?`${selected.length} corner${selected.length===1?'':'s'}`:'No corners';picker.querySelector('.corner-all').checked=selected.length===options.length;picker.querySelector('.corner-none').checked=selected.length===0;picker.querySelector('.corner-warning').hidden=selected.length>0;row.classList.toggle('corner-error',selected.length===0)}
function bindCornerPicker(row){const picker=row.querySelector('.corner-picker');picker.querySelector('.corner-all').onchange=event=>{picker.querySelectorAll('.corner-option').forEach(option=>option.checked=event.target.checked);updateCornerPicker(row)};picker.querySelector('.corner-none').onchange=event=>{if(event.target.checked)picker.querySelectorAll('.corner-option').forEach(option=>option.checked=false);updateCornerPicker(row)};picker.querySelectorAll('.corner-option').forEach(option=>option.onchange=()=>updateCornerPicker(row));updateCornerPicker(row)}
function selectedCorners(row,label){const corners=[...row.querySelectorAll('.corner-option:checked')].map(option=>option.value);if(!corners.length){row.classList.add('corner-error');row.querySelector('.corner-warning').hidden=false;throw new Error(`${label} has no corner selected.`)}return corners}
function updateObjectiveTarget(row){const target=row.querySelector('.target');const enabled=row.querySelector('.direction').value==='target';target.hidden=!enabled;target.disabled=!enabled;if(!enabled)target.value=''}
function applyMetricDefinition(row,definition={}){if(definition.output_key)row.querySelector('.output-key').value=definition.output_key;if(definition.aggregation)row.querySelector('.aggregation').value=definition.aggregation;const selected=new Set(definition.corners??defaultCornerNames());row.querySelectorAll('.corner-option').forEach(option=>option.checked=selected.has(option.value));updateCornerPicker(row)}
function addObjective(definition={}){const row=document.createElement('div');row.className='metric-row objective';row.innerHTML=`<select class="output-key">${outputOptions()}</select><select class="aggregation"><option>mean</option><option>min</option><option>max</option><option>first</option><option>last</option></select>${cornerPicker()}<select class="direction"><option value="minimize">Minimize</option><option value="maximize">Maximize</option><option value="target">Target</option></select><input class="target" type="text" inputmode="decimal" placeholder="Target value"><button class="danger remove">Remove</button>`;row.querySelector('.direction').onchange=()=>updateObjectiveTarget(row);row.querySelector('.remove').onclick=()=>{row.remove();renderAlgorithmSettings()};bindCornerPicker(row);applyMetricDefinition(row,definition);row.querySelector('.direction').value=definition.direction||'minimize';if(definition.target!=null)row.querySelector('.target').value=definition.target;updateObjectiveTarget(row);$('objectiveRows').appendChild(row);renderAlgorithmSettings()}
function addConstraint(definition={}){const row=document.createElement('div');row.className='metric-row constraint';row.innerHTML=`<select class="output-key">${outputOptions()}</select><select class="aggregation"><option>mean</option><option>min</option><option>max</option><option>first</option><option>last</option></select>${cornerPicker()}<select class="operator"><option value="<=">Maximum</option><option value=">=">Minimum</option></select><input class="limit" type="text" inputmode="decimal" placeholder="Limit value"><button class="danger remove">Remove</button>`;row.querySelector('.remove').onclick=()=>row.remove();bindCornerPicker(row);applyMetricDefinition(row,definition);row.querySelector('.operator').value=definition.operator||'<=';if(definition.limit!=null)row.querySelector('.limit').value=definition.limit;$('constraintRows').appendChild(row)}

function renderPrepared(){const prepared=state.prepared;const counts=prepared.hierarchy.designs.reduce((total,design)=>{Object.keys(total).forEach(key=>total[key]+=design.hierarchy.counts[key]||0);return total},{cells:0,instances:0,hierarchical_instances:0,devices:0,parameters:0,tunable_parameters:0});const optimizable=prepared.parameters.filter(parameter=>parameter.optimizable);state.parameterConfig={};state.rangeValidationResults={};state.rangeValidationRequested={};state.rangeValidationJobId=null;clearTimeout(state.rangeValidationTimer);optimizable.forEach(parameter=>{const unit=physicalUnit(parameter);state.parameterConfig[parameter.parameter_id]={selected:Boolean(parameter.default_selected),unit,minimum:boundDefault(parameter,'min',unit),maximum:boundDefault(parameter,'max',unit),scale:'linear',value_type:parameter.value_type||'float'}});state.parameterForest=buildParameterForest();state.parameterOpen=new Set(state.parameterForest.map(node=>node.id));const resident=prepared.resident_validation||{};const residentText=resident.state==='ready'?'<span class="good">Range validation session ready</span>':`<span class="bad">Range validation session unavailable: ${esc(resident.message||'unknown')}</span>`;const setupDb=prepared.setup.source.setup_db||prepared.setup.source.maestro_sdb||prepared.setup.source.data_sdb||prepared.setup_path||prepared.maestro_path||'';const setupBackend=String(prepared.setup.backend||prepared.setup_locator?.backend||'ADE').toUpperCase();$('setupSummary').innerHTML=`Backend <b>${esc(setupBackend)}</b> · Tests <b>${prepared.setup.tests.length}</b> · Corners <b>${prepared.setup.corners.length}</b> · Outputs <b>${prepared.outputs.length}</b> · ${residentText} · Setup <span class="path">${esc(setupDb)}</span>`;$('hierarchySummary').innerHTML=`Cells <b>${counts.cells}</b> · Hierarchical instances <b>${counts.hierarchical_instances}</b> · Devices <b>${counts.devices}</b> · Meaningful parameters <b>${optimizable.length}</b> · Selected <b id="selectedParameterCount">0</b>`;$('analysisSummary').innerHTML=`<b>Analyses for ${esc(prepared.setup.selected_test)}</b><div>${(prepared.setup.tests[0]?.analyses||[]).map(analysis=>`<label><input type="checkbox" class="analysis-option" value="${esc(analysis.name)}" ${analysis.enabled!==false?'checked':''}> ${esc(analysis.name)}</label> `).join('')||'None'}</div>Outputs: ${prepared.outputs.map(output=>esc(output.key)).join('<br>')}`;$('objectiveRows').innerHTML='';$('constraintRows').innerHTML='';$('rangeValidationSummary').textContent='Optional PDK callback validation has not been run. If skipped, the first PDK-adjusted candidate stops the run.';renderPdkContext(prepared.eda_context?.pdk);addObjective();renderParameters();$('runButton').disabled=false;$('saveConfigButton').disabled=false;$('validateRangesButton').disabled=false;updateRangeApplyButton()}
function resetPrepared(){state.preparedId=null;state.prepared=null;state.inspectionId=null;state.selectedTest=null;state.parameterConfig={};clearTimeout(state.rangeValidationTimer);$('runButton').disabled=true;$('saveConfigButton').disabled=true;$('validateRangesButton').disabled=true;$('applyCellsButton').disabled=true;$('cellScopes').innerHTML='';$('parameterTree').innerHTML='';$('objectiveRows').innerHTML='';$('constraintRows').innerHTML='';$('analysisSummary').innerHTML=''}
async function loadSetup(){const token=++state.loadToken;resetPrepared();state.testInspectionId=null;$('inspectCellsButton').disabled=true;$('testSelect').disabled=true;try{$('loadButton').disabled=true;const path=$('maestroPath').value.trim();if(!path)throw new Error('Enter or select an ADE setup path.');$('setupSummary').textContent='Reading saved Tests...';localStorage.setItem('crescendo.adeSetupPath',path);const data=await api('/api/inspect-tests',{method:'POST',body:JSON.stringify({path,backend:'auto'})});if(token!==state.loadToken)return;state.testInspectionId=data.test_inspection_id;const tests=data.preview.tests||[];$('testSelect').innerHTML='<option value="">Select a Test</option>'+tests.map(test=>`<option value="${esc(test.name)}">${esc(test.name)}</option>`).join('');$('testSelect').disabled=false;$('setupSummary').textContent=`${tests.length} Tests found. Select one Test to inspect.`;if(tests.length===1){$('testSelect').value=tests[0].name;$('inspectCellsButton').disabled=false}}catch(error){if(token===state.loadToken)$('setupSummary').innerHTML=`<span class="bad">${esc(error.message)}</span>`}finally{if(token===state.loadToken)$('loadButton').disabled=false}}
async function inspectSelectedTest(){const test=$('testSelect').value;const token=++state.loadToken;resetPrepared();state.selectedTest=test;if(!test||!state.testInspectionId)return;try{$('inspectCellsButton').disabled=true;$('setupSummary').textContent=`Inspecting cells for ${test}...`;const data=await api('/api/inspect-test-cells',{method:'POST',body:JSON.stringify({test_inspection_id:state.testInspectionId,test_name:test,max_depth:32})});if(token!==state.loadToken||test!==$('testSelect').value)return;state.inspectionId=data.inspection_id;const scopes=data.inspection.cell_scopes||[];$('cellScopes').innerHTML=scopes.map(row=>`<label><input type="checkbox" class="cell-scope" value="${esc(row.scope_id)}"> ${esc(row.design?.library||'')}/${esc(row.design?.cell||'')} ${esc(row.hierarchy_path||'/')}</label>`).join('')||'<span class="bad">No selectable cells.</span>';$('applyCellsButton').disabled=!scopes.length;$('setupSummary').textContent=`Select one or more cells for ${test}.`}catch(error){if(token===state.loadToken)$('setupSummary').innerHTML=`<span class="bad">${esc(error.message)}</span>`}finally{if(token===state.loadToken)$('inspectCellsButton').disabled=!$('testSelect').value}}
async function applyCells(){const token=state.loadToken,test=state.selectedTest,inspection=state.inspectionId;try{const scopes=[...document.querySelectorAll('.cell-scope:checked')].map(input=>input.value);if(!scopes.length)throw new Error('Select at least one cell.');$('applyCellsButton').disabled=true;$('setupSummary').textContent=`Preparing selected cells for ${test}...`;const data=await api('/api/prepare-cells',{method:'POST',body:JSON.stringify({inspection_id:inspection,scope_ids:scopes})});if(token!==state.loadToken||test!==$('testSelect').value)return;if(state.pendingConfig&&state.pendingConfig.execution_selection.tests[0]!==test)throw new Error('Configuration belongs to a different Test.');state.preparedId=data.prepared_id;state.prepared=data.prepared;renderPrepared();if(state.pendingConfig)applyDesignConfig(state.pendingConfig)}catch(error){if(token===state.loadToken)$('setupSummary').innerHTML=`<span class="bad">${esc(error.message)}</span>`}finally{if(token===state.loadToken)$('applyCellsButton').disabled=!state.inspectionId}}


async function browse(path){const data=await api(`/api/browse${path?`?path=${encodeURIComponent(path)}`:''}`);state.browsePath=data.path;$('browserPath').textContent=data.path;$('browserUp').disabled=!data.parent;$('browserUp').dataset.path=data.parent||'';$('useCurrent').hidden=!data.is_setup;$('browserRows').innerHTML=data.entries.length?data.entries.map(entry=>{const backend=entry.setup_backend?entry.setup_backend.toUpperCase():'ADE';const tag=entry.ambiguous_setup?'Multiple ADE setups':`${backend} setup`;return `<div class="browser-row"><button class="browser-open" data-open="${esc(entry.path)}"><span class="folder-icon">▱</span><span class="path">${esc(entry.name)}</span>${entry.is_setup||entry.ambiguous_setup?`<span class="setup-tag">${esc(tag)}</span>`:''}</button><div class="browser-actions">${entry.is_setup?`<button class="secondary compact" data-select="${esc(entry.path)}">Select</button>`:''}</div></div>`}).join(''):'<div class="empty-state">No visible directories.</div>';$('browserRows').querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>browse(button.dataset.open));$('browserRows').querySelectorAll('[data-select]').forEach(button=>button.onclick=()=>selectAdeSetup(button.dataset.select))}
async function openBrowser(){try{$('browserModal').hidden=false;await browse($('maestroPath').value.trim()||null)}catch(error){$('browserRows').innerHTML=`<div class="empty-state bad">${esc(error.message)}</div>`}}
async function nativeBrowse(){const button=$('nativeBrowseButton');try{button.disabled=true;$('setupSummary').textContent='Waiting for the native Linux file dialog...';const path=$('maestroPath').value.trim();const data=await api('/api/native-browse',{method:'POST',body:JSON.stringify(path?{path}:{})});if(!data.cancelled){selectAdeSetup(data.path);$('setupSummary').innerHTML=`Selected <span class="path">${esc(data.setup_db||data.maestro_sdb||data.path)}</span>`}else $('setupSummary').textContent='Native file selection cancelled.'}catch(error){$('setupSummary').innerHTML=`Native dialog unavailable; using server browser. <span class="bad">${esc(error.message)}</span>`;await openBrowser()}finally{button.disabled=false}}
function closeBrowser(){$('browserModal').hidden=true}
function selectAdeSetup(path){$('maestroPath').value=path;localStorage.setItem('crescendo.adeSetupPath',path);closeBrowser()}

function collectVariables(){syncParameterInputs();return Object.entries(state.parameterConfig).filter(([,config])=>config.selected).map(([parameter_id,config])=>({parameter_id,minimum:parsePhysicalInput(config.minimum,config.unit),maximum:parsePhysicalInput(config.maximum,config.unit),scale:config.scale,value_type:config.value_type}))}
async function validateAllRanges(){const token=state.loadToken,preparedId=state.preparedId;const button=$('validateRangesButton');try{const variables=collectVariables().map(({parameter_id,minimum,maximum})=>({parameter_id,minimum,maximum}));if(!variables.length)throw new Error('Select at least one optimizable parameter.');button.disabled=true;state.rangeValidationResults={};state.rangeValidationRequested=Object.fromEntries(variables.map(variable=>[variable.parameter_id,variable]));updateRangeApplyButton();renderParameters();$('rangeValidationSummary').textContent=`Queued optional callback validation for ${variables.length} parameters. Optimization remains available while validation runs.`;const data=await api('/api/range-validation/start',{method:'POST',body:JSON.stringify({prepared_id:state.preparedId,variables})});if(token!==state.loadToken||preparedId!==state.preparedId)return;state.rangeValidationJobId=data.job_id;pollRangeValidation()}catch(error){if(token!==state.loadToken)return;button.disabled=false;$('rangeValidationSummary').innerHTML=`<span class="bad">${esc(error.message)}</span> Validation is optional; without it, the first PDK-adjusted candidate stops the run.`}}
async function pollRangeValidation(){const token=state.loadToken,jobId=state.rangeValidationJobId;clearTimeout(state.rangeValidationTimer);try{const job=await api(`/api/range-validation/status?job_id=${encodeURIComponent(state.rangeValidationJobId)}`);if(token!==state.loadToken||jobId!==state.rangeValidationJobId)return;state.rangeValidationResults={};(job.results||[]).forEach(row=>{if(!state.rangeValidationRequested[row.parameter_id])return;(state.rangeValidationResults[row.parameter_id]||(state.rangeValidationResults[row.parameter_id]=[])).push(row)});renderParameters();const adjusted=(job.results||[]).filter(row=>row.status==='pdk_adjusted').length;const failed=(job.results||[]).filter(row=>row.status==='validation_failed').length;const terminal=['completed','failed','cancelled'].includes(job.state);$('rangeValidationSummary').innerHTML=`${esc(job.state)} · ${esc(job.message)} · PDK adjusted <b>${adjusted}</b> · Failed <b>${failed}</b>.${job.state==='completed'&&adjusted?' Apply the legal ranges before starting.':' Validation remains optional.'}`;if(terminal){$('validateRangesButton').disabled=false;updateRangeApplyButton();return}state.rangeValidationTimer=setTimeout(pollRangeValidation,1000)}catch(error){if(token!==state.loadToken)return;$('validateRangesButton').disabled=false;updateRangeApplyButton();$('rangeValidationSummary').innerHTML=`<span class="bad">${esc(error.message)}</span> Validation is optional; without it, the first PDK-adjusted candidate stops the run.`}}
function collectObjectives(){return [...document.querySelectorAll('.objective')].map((row,index)=>{const result={output_key:row.querySelector('.output-key').value,aggregation:row.querySelector('.aggregation').value,corners:selectedCorners(row,`Objective ${index+1}`),direction:row.querySelector('.direction').value};if(result.direction==='target')result.target=row.querySelector('.target').value.trim();return result})}
function collectConstraints(){return [...document.querySelectorAll('.constraint')].map((row,index)=>({output_key:row.querySelector('.output-key').value,aggregation:row.querySelector('.aggregation').value,corners:selectedCorners(row,`Constraint ${index+1}`),operator:row.querySelector('.operator').value,limit:row.querySelector('.limit').value.trim()}))}

function buildDesignConfig(){if(!state.prepared)throw new Error('Load an ADE setup first.');return {schema_version:'crescendo.design_config.v1',execution_selection:{tests:[state.prepared.setup.selected_test],analyses:{[state.prepared.setup.selected_test]:[...document.querySelectorAll('.analysis-option:checked')].map(item=>item.value)}},ade_setup:{path:$('maestroPath').value.trim(),backend:state.prepared.setup?.backend||state.prepared.setup_locator?.backend||'auto'},optimization:{variables:collectVariables(),objectives:collectObjectives(),constraints:collectConstraints(),run:{generations:Number($('generations').value),jobs:1,candidate_timeout_seconds:Number($('candidateTimeout').value),...collectAlgorithmSettings()}}}}
function applyDesignConfig(document){if(document?.schema_version!=='crescendo.design_config.v1')throw new Error('Unsupported design config; expected crescendo.design_config.v1.');const analyses=document.execution_selection?.analyses?.[state.prepared?.setup?.selected_test];if(analyses)window.document.querySelectorAll('.analysis-option').forEach(input=>input.checked=analyses.includes(input.value));const optimization=document.optimization||{};Object.values(state.parameterConfig).forEach(config=>config.selected=false);const missingParameters=[];(optimization.variables||[]).forEach(variable=>{const config=state.parameterConfig[variable.parameter_id];if(!config){missingParameters.push(variable.parameter_id);return}config.selected=true;config.minimum=config.value_type==='integer'?String(Math.round(Number(variable.minimum))):formatPhysical(variable.minimum,config.unit);config.maximum=config.value_type==='integer'?String(Math.round(Number(variable.maximum))):formatPhysical(variable.maximum,config.unit);config.scale=config.value_type==='integer'?'linear':variable.scale||'linear'});$('objectiveRows').innerHTML='';$('constraintRows').innerHTML='';(optimization.objectives||[]).forEach(addObjective);(optimization.constraints||[]).forEach(addConstraint);if(!(optimization.objectives||[]).length)addObjective();const run=optimization.run||{};if(run.generations!=null)$('generations').value=run.generations;$('jobs').value=1;if(run.candidate_timeout_seconds!=null)$('candidateTimeout').value=run.candidate_timeout_seconds;renderParameters();applyAlgorithmSettings(run.algorithm||'nsga2',run.algorithm_parameters||{});configureTradeoff({objectives:optimization.objectives||[],constraints:optimization.constraints||[]});state.pendingConfig=null;return missingParameters}
function saveDesignConfig(){try{downloadJson('crescendo-design-config.json',buildDesignConfig());$('configMessage').innerHTML='<span class="good">Design config saved.</span>'}catch(error){$('configMessage').innerHTML=`<span class="bad">${esc(error.message)}</span>`}}
async function loadDesignConfigFile(){const token=++state.loadToken;try{const document=await readJsonFile($('configFileInput'));if(token!==state.loadToken)return;const tests=document.execution_selection?.tests;if(!Array.isArray(tests)||tests.length!==1)throw new Error('This configuration does not identify exactly one Test and is incompatible.');state.pendingConfig=document;$('maestroPath').value=document.ade_setup?.path||document.setup_locator?.path||document.maestro?.path||'';await loadSetup();if(state.loadToken!==token+1)return;$('configMessage').textContent=`Select Test ${tests[0]}, inspect and apply cells to restore settings.`}catch(error){if(token!==state.loadToken)return;$('configMessage').innerHTML=`<span class="bad">${esc(error.message)}</span>`}}


async function startRun(){const token=state.loadToken,preparedId=state.preparedId;try{const variables=collectVariables();const objectives=collectObjectives();if(!variables.length)throw new Error('Select at least one optimizable parameter.');if(!objectives.length)throw new Error('Add at least one objective.');const generations=Number($('generations').value);if(!Number.isInteger(generations)||generations<10||generations>100)throw new Error('Generations must be between 10 and 100.');const candidateTimeout=Number($('candidateTimeout').value);if(!Number.isFinite(candidateTimeout)||candidateTimeout<30)throw new Error('Candidate timeout must be at least 30 seconds.');const selected_test=state.prepared.setup.selected_test;const analyses=[...document.querySelectorAll('.analysis-option:checked')].map(item=>item.value);if(document.querySelectorAll('.analysis-option').length&&!analyses.length)throw new Error('Select at least one analysis.');const spec={selected_test,execution_selection:{tests:[selected_test],analyses:{[selected_test]:analyses}},evaluator:'real',generations,jobs:1,candidate_timeout_seconds:candidateTimeout,variables,objectives,constraints:collectConstraints(),...collectAlgorithmSettings()};const data=await api('/api/start',{method:'POST',body:JSON.stringify({prepared_id:state.preparedId,spec})});if(token!==state.loadToken||preparedId!==state.preparedId)return;state.runId=data.run_id;state.liveSpec=spec;state.liveCandidates=[];state.selectedCandidateId=null;$('runButton').disabled=true;$('stopButton').disabled=false;$('saveCheckpointButton').disabled=false;$('exportCsvButton').disabled=false;$('resultRows').innerHTML='';renderCandidateDetail([]);configureTradeoff(spec);poll()}catch(error){if(token!==state.loadToken)return;$('runState').innerHTML=`<span class="bad">${esc(error.message)}</span>`}}

async function saveCheckpoint(){try{if(!state.runId)throw new Error('No optimization run is available.');const checkpoint=await api(`/api/checkpoint?run_id=${encodeURIComponent(state.runId)}`);downloadJson(`${state.runId}-checkpoint.json`,checkpoint);$('checkpointMessage').innerHTML='<span class="good">Checkpoint saved.</span>';loadRecentRuns()}catch(error){$('checkpointMessage').innerHTML=`<span class="bad">${esc(error.message)}</span>`}}
function checkpointDesignConfig(checkpoint){const spec=checkpoint.spec||{};const setup=checkpoint.manifest?.setup_locator||{path:checkpoint.manifest?.maestro_path||'',backend:'maestro'};return {schema_version:'crescendo.design_config.v1',ade_setup:setup,optimization:{variables:spec.variables||[],objectives:spec.objectives||[],constraints:spec.constraints||[],run:{generations:spec.generations,jobs:1,candidate_timeout_seconds:spec.candidate_timeout_seconds,algorithm:spec.algorithm,algorithm_parameters:spec.algorithm_parameters||{population:spec.population,seed:spec.seed}}}}}
async function resumeCheckpoint(checkpoint,useCurrentPath=false){const token=++state.loadToken;resetPrepared();try{if(!checkpoint.spec?.selected_test)throw new Error('Checkpoint does not identify one Test and is incompatible.');const path=useCurrentPath?$('maestroPath').value.trim():null;const body={checkpoint};if(path)body.path=path;$('checkpointMessage').textContent='Reloading the ADE setup and restoring the optimization state...';const data=await api('/api/resume',{method:'POST',body:JSON.stringify(body)});if(token!==state.loadToken||data.prepared?.setup?.selected_test!==checkpoint.spec.selected_test)return;state.selectedTest=checkpoint.spec.selected_test;state.preparedId=data.prepared_id;state.prepared=data.prepared;$('maestroPath').value=state.prepared.setup_locator?.path||state.prepared.setup_path||state.prepared.maestro_path||checkpoint.manifest?.setup_locator?.path||checkpoint.manifest?.maestro_path||'';renderPrepared();applyDesignConfig(checkpointDesignConfig(checkpoint));state.pendingCheckpoint=null;$('loadCheckpointButton').textContent='Load Checkpoint';state.runId=data.run_id;state.liveSpec=checkpoint.spec||{};state.liveCandidates=[];state.selectedCandidateId=null;$('runButton').disabled=true;$('stopButton').disabled=false;$('saveCheckpointButton').disabled=false;$('exportCsvButton').disabled=false;$('checkpointMessage').innerHTML='<span class="good">Checkpoint restored; the saved state is opening or continuing.</span>';poll()}catch(error){if(token!==state.loadToken)return;state.pendingCheckpoint=checkpoint;$('loadCheckpointButton').textContent='Resume Loaded Checkpoint';$('checkpointMessage').innerHTML=`<span class="bad">${esc(error.message)}</span> Load the matching ADE setup on this machine, then click Resume Loaded Checkpoint.`}}
async function loadCheckpointFile(){try{const checkpoint=await readJsonFile($('checkpointFileInput'));state.pendingCheckpoint=checkpoint;await resumeCheckpoint(checkpoint,false)}catch(error){$('checkpointMessage').innerHTML=`<span class="bad">${esc(error.message)}</span>`}}
function loadOrResumeCheckpoint(){if(state.pendingCheckpoint)resumeCheckpoint(state.pendingCheckpoint,true);else $('checkpointFileInput').click()}
function recentRunState(run){return String(run.state||run.status?.state||'unknown')}
function recentRunId(run){return String(run.run_id||run.id||'')}
async function downloadRunCheckpoint(runId){try{const checkpoint=await api(`/api/checkpoint?run_id=${encodeURIComponent(runId)}`);downloadJson(`${runId}-checkpoint.json`,checkpoint);$('checkpointMessage').innerHTML='<span class="good">Latest local checkpoint saved.</span>'}catch(error){$('checkpointMessage').innerHTML=`<span class="bad">${esc(error.message)}</span>`}}
async function resumeLocalRun(runId){try{const checkpoint=await api(`/api/checkpoint?run_id=${encodeURIComponent(runId)}`);state.pendingCheckpoint=checkpoint;await resumeCheckpoint(checkpoint,false);loadRecentRuns()}catch(error){$('checkpointMessage').innerHTML=`<span class="bad">${esc(error.message)}</span>`}}
async function loadRecentRuns(){try{const data=await api('/api/runs');const runs=(data.runs||[]).filter(run=>run.checkpoint_available).slice(0,12);$('recentRunsSummary').textContent=runs.length?`${runs.length} checkpoint${runs.length===1?'':'s'} available`:'No checkpoints';$('recentRunsList').innerHTML=runs.map(run=>{const runId=recentRunId(run);const active=run.active===true;const revision=run.checkpoint_revision??run.revision;const continuation=run.continuation_id?String(run.continuation_id).slice(0,12):'';return `<div class="recent-run"><div class="recent-run-meta"><b class="mono">${esc(runId)}</b><span>${esc(recentRunState(run))}${active?' · active':''}</span>${revision!=null?`<span>Revision ${esc(revision)}</span>`:''}${continuation?`<span class="muted">Continuation ${esc(continuation)}</span>`:''}</div><div class="recent-run-actions"><button class="secondary" data-download-run="${esc(runId)}">Download</button><button data-resume-run="${esc(runId)}" ${active?'disabled':''}>${active?'Active':'Resume Latest'}</button></div></div>`}).join('')||'<div class="muted">No local checkpoint is available yet.</div>';document.querySelectorAll('[data-download-run]').forEach(button=>button.onclick=()=>downloadRunCheckpoint(button.dataset.downloadRun));document.querySelectorAll('[data-resume-run]').forEach(button=>button.onclick=()=>resumeLocalRun(button.dataset.resumeRun))}catch(error){$('recentRunsSummary').textContent='Unavailable';$('recentRunsList').innerHTML=`<div class="bad">${esc(error.message)}</div>`}}
async function exportCandidatesCsv(){try{if(!state.runId)throw new Error('No optimization run is available.');const response=await fetch(`/api/candidates.csv?run_id=${encodeURIComponent(state.runId)}`);if(!response.ok){const payload=await response.json();throw new Error(payload.error||response.statusText)}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`${state.runId}-candidates.csv`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('csvMessage').innerHTML='<span class="good">CSV exported.</span>'}catch(error){$('csvMessage').innerHTML=`<span class="bad">${esc(error.message)}</span>`}}

function metricByKey(metrics,key){return (metrics||[]).find(metric=>metric.output_key===key)}
function parameterById(parameterId){return (state.prepared?.parameters||[]).find(parameter=>parameter.parameter_id===parameterId)}
function metricLabel(definition){const corners=(definition.corners||[]).join(', ');return `${esc(definition.output_key)}${corners?` <span class="metric-corners">${esc(corners)}</span>`:''}`}
function candidateStatus(row){if(row.failure_class==='source_integrity')return {label:'Source Changed · Run Aborted',className:'bad'};if(row.status==='infrastructure_failed')return {label:'Infrastructure Failed',className:'bad'};if(row.status==='failed')return {label:'Simulation / Evaluation Failed',className:'bad'};if(row.status==='completed'&&row.metrics?.feasible===false)return {label:'Completed · Constraints Not Met',className:'bad'};if(row.status==='completed')return {label:'Completed',className:'good'};if(row.status==='queued')return {label:'Queued',className:'pending'};return {label:'Running',className:'pending'}}
function renderMetricStack(definitions,metrics,type,rowStatus){if(!definitions.length)return '<span class="muted">None</span>';const terminal=['completed','failed','infrastructure_failed'].includes(rowStatus);return `<div class="metric-stack">${definitions.map((definition,index)=>{const metric=metrics[index];const missing=!metric||metric.value==null||!Number.isFinite(Number(metric.value));const pending=!terminal&&missing;const failed=terminal&&(missing||metric.failed||metric.penalized);const value=pending?'Pending':failed?'Failed':number(metric.value);const outcome=type==='constraint'&&!pending&&!failed?`<span class="${metric.satisfied?'metric-pass':'metric-fail'}">${metric.satisfied?'Pass':'Fail'}</span>`:'';const valueClass=pending?'pending':failed?'bad':'';return `<div class="metric-line"><span class="metric-name">${metricLabel(definition)}</span><span class="metric-current ${valueClass}">${value}</span>${outcome}</div>`}).join('')}</div>`}
function renderCandidateDetail(rows){const body=$('candidateDetailBody');const row=rows.find(candidate=>candidate.candidate_id===state.selectedCandidateId);if(!row){body.className='candidate-detail-empty';body.innerHTML='Select a candidate to inspect its variables.';return}const status=candidateStatus(row);const variables=Object.entries(row.values||{});body.className='';body.innerHTML=`<div class="candidate-detail-head"><b>${esc(row.candidate_id)}</b><span class="${status.className}">${status.label}</span></div><div class="candidate-variable-list">${variables.map(([parameterId,value])=>{const parameter=parameterById(parameterId);const unit=parameter?physicalUnit(parameter):'';const path=parameter?.hierarchy_path||parameter?.instance_path||'';const name=parameter?.name||parameterId;const prompt=parameter?.prompt||parameter?.cdf_name||'';const display=unit?`${formatPhysical(value,unit)} ${unit}`:number(value,8);return `<div class="candidate-variable"><div><b>${esc(name)}</b>${path?`<span class="path">${esc(path)}</span>`:''}${prompt?`<small>${esc(prompt)}</small>`:''}</div><strong>${esc(display)}</strong></div>`}).join('')||'<div class="candidate-detail-empty">No variable values were recorded.</div>'}</div>`}
function renderCandidates(rows,spec){const objectives=spec.objectives||[];const constraints=spec.constraints||[];$('resultHead').innerHTML=['Candidate','Generation','Status','Feasible','Objectives','Constraints'].map(label=>`<th>${label}</th>`).join('');$('resultRows').innerHTML=rows.map(row=>{const metrics=row.metrics||{};const status=candidateStatus(row);const infrastructure=row.status==='infrastructure_failed';const finalized=['completed','failed','infrastructure_failed'].includes(row.status);const feasible=infrastructure?'N/A':finalized?(metrics.feasible===true?'Yes':'No'):'Pending';const feasibleClass=metrics.feasible===true?'good':finalized?'bad':'pending';const objectiveValues=infrastructure?'<span class="muted">N/A · replacement sampled</span>':renderMetricStack(objectives,metrics.objectives||[],'objective',row.status);const constraintValues=infrastructure?'<span class="muted">N/A · replacement sampled</span>':renderMetricStack(constraints,metrics.constraints||[],'constraint',row.status);const selected=row.candidate_id===state.selectedCandidateId;return `<tr class="${selected?'candidate-row-selected':''}"><td><button class="candidate-select ${selected?'selected':''}" data-candidate-select="${esc(row.candidate_id)}">${esc(row.candidate_id)}</button></td><td>${Number(row.generation)+1}</td><td class="${status.className}" title="${esc(row.error||status.label)}">${status.label}</td><td class="${feasibleClass}">${feasible}</td><td>${objectiveValues}</td><td>${constraintValues}</td></tr>`}).join('');document.querySelectorAll('[data-candidate-select]').forEach(button=>button.onclick=()=>{state.selectedCandidateId=button.dataset.candidateSelect;renderCandidates(rows,spec)});renderCandidateDetail(rows)}

function configureTradeoff(spec){const objectives=spec.objectives||[];const options=objectives.map((objective,index)=>`<option value="${index}">${esc(objective.output_key)}</option>`).join('');$('tradeoffX').innerHTML=options;$('tradeoffY').innerHTML=options;if(objectives.length>1)$('tradeoffY').value='1';const enabled=objectives.length>1;$('tradeoffEmpty').hidden=enabled;$('tradeoffPlot').hidden=!enabled;if(enabled)renderTradeoff(state.liveCandidates,spec)}
function renderTradeoff(rows,spec){const objectives=spec.objectives||[];if(objectives.length<2)return;const xIndex=Number($('tradeoffX').value||0);const yIndex=Number($('tradeoffY').value||1);const xDefinition=objectives[xIndex];const yDefinition=objectives[yIndex];const points=rows.filter(row=>row.status==='completed'&&row.metrics?.feasible).map(row=>{const x=metricByKey(row.metrics.objectives,xDefinition.output_key);const y=metricByKey(row.metrics.objectives,yDefinition.output_key);return x&&y&&Number.isFinite(Number(x.value))&&Number.isFinite(Number(y.value))?{x:Number(x.value),y:Number(y.value),generation:Number(row.generation),id:row.candidate_id}:null}).filter(Boolean);const svg=$('tradeoffChart');if(!points.length){svg.innerHTML='<text x="480" y="210" text-anchor="middle" class="axis-label">Waiting for feasible completed individuals...</text>';$('tradeoffLegend').innerHTML='';return}let xMin=Math.min(...points.map(point=>point.x)),xMax=Math.max(...points.map(point=>point.x)),yMin=Math.min(...points.map(point=>point.y)),yMax=Math.max(...points.map(point=>point.y));const xPad=(xMax-xMin||Math.max(Math.abs(xMax),1))*.08;const yPad=(yMax-yMin||Math.max(Math.abs(yMax),1))*.08;xMin-=xPad;xMax+=xPad;yMin-=yPad;yMax+=yPad;const left=88,right=925,top=28,bottom=350;const sx=value=>left+(value-xMin)/(xMax-xMin)*(right-left);const sy=value=>bottom-(value-yMin)/(yMax-yMin)*(bottom-top);let markup='';for(let index=0;index<=5;index++){const xValue=xMin+(xMax-xMin)*index/5;const yValue=yMin+(yMax-yMin)*index/5;const x=sx(xValue),y=sy(yValue);markup+=`<line class="grid-line" x1="${x}" y1="${top}" x2="${x}" y2="${bottom}"/><text class="tick-label" x="${x}" y="${bottom+22}" text-anchor="middle">${number(xValue,4)}</text>`;markup+=`<line class="grid-line" x1="${left}" y1="${y}" x2="${right}" y2="${y}"/><text class="tick-label" x="${left-12}" y="${y+4}" text-anchor="end">${number(yValue,4)}</text>`}markup+=`<line class="axis" x1="${left}" y1="${bottom}" x2="${right}" y2="${bottom}"/><line class="axis" x1="${left}" y1="${top}" x2="${left}" y2="${bottom}"/><text class="axis-label" x="${(left+right)/2}" y="405" text-anchor="middle">${esc(xDefinition.output_key)}</text><text class="axis-label" transform="translate(22 ${(top+bottom)/2}) rotate(-90)" text-anchor="middle">${esc(yDefinition.output_key)}</text>`;markup+=points.map(point=>`<circle class="point" cx="${sx(point.x)}" cy="${sy(point.y)}" r="5" fill="${palette[point.generation%palette.length]}"><title>${esc(point.id)} · generation ${point.generation+1} · x=${number(point.x)} · y=${number(point.y)}</title></circle>`).join('');svg.innerHTML=markup;const counts={};points.forEach(point=>counts[point.generation]=(counts[point.generation]||0)+1);$('tradeoffLegend').innerHTML=Object.keys(counts).sort((a,b)=>Number(a)-Number(b)).map(generation=>`<span class="legend-item"><span class="legend-dot" style="background:${palette[Number(generation)%palette.length]}"></span>Generation ${Number(generation)+1}: ${counts[generation]} feasible points</span>`).join('')}

async function poll(){clearTimeout(state.timer);try{const progress=await api(`/api/progress?run_id=${encodeURIComponent(state.runId)}`);const status=progress.status;const spec=(progress.spec?.objectives?.length?progress.spec:state.liveSpec)||{objectives:[],constraints:[]};state.liveSpec=spec;state.liveCandidates=progress.candidates||[];$('runState').textContent=`${status.state} · ${status.message}`;$('progress').max=status.total_candidates||1;$('progress').value=(status.completed_candidates||0)+(status.failed_candidates||0)+(status.infrastructure_failed_candidates||0);renderCandidates(state.liveCandidates,spec);configureTradeoff(spec);const completed=status.completed_candidates||0;const failed=status.failed_candidates||0;const infrastructure=status.infrastructure_failed_candidates||0;const feasible=state.liveCandidates.filter(row=>row.status==='completed'&&row.metrics?.feasible).length;$('resultSummary').innerHTML=`Completed <b>${completed}</b> · Failed <b>${failed}</b> · Infrastructure replaced <b>${infrastructure}</b> · Feasible <b>${feasible}</b> · Run <span class="path">${esc(status.run_root)}</span>`;if(status.state==='completed'||status.state==='stopped'){const result=await api(`/api/result?run_id=${encodeURIComponent(state.runId)}`);const representative=result.representative||result.best||{};const representativeLabel=(spec.objectives||[]).length>1?'Representative':'Best';$('resultSummary').innerHTML=`${status.state==='stopped'?'Stopped':'Completed'} · Completed <b>${completed}</b> · Failed <b>${failed}</b> · Infrastructure replaced <b>${infrastructure}</b> · Pareto <b>${result.pareto_front.length}</b> · ${representativeLabel} <b>${esc(representative.candidate_id||'N/A')}</b> · Run <span class="path">${esc(result.run_root)}</span>`;$('runButton').disabled=false;$('stopButton').disabled=true;loadRecentRuns();return}if(status.state==='failed'){$('runButton').disabled=false;$('stopButton').disabled=true;loadRecentRuns();return}state.timer=setTimeout(poll,1200)}catch(error){$('runState').textContent=`${error.message} · Check Recent Local Runs to recover.`;loadRecentRuns();state.timer=setTimeout(poll,2000)}}
async function stopRun(){if(state.runId)await api('/api/stop',{method:'POST',body:JSON.stringify({run_id:state.runId})})}
async function exitOptimizer(){const button=$('exitOptimizerButton');if(!window.confirm('Stop active work, close owned Cadence sessions, and exit the optimizer?'))return;try{button.disabled=true;button.textContent='Exiting...';const result=await api('/api/exit',{method:'POST',body:'{}'});$('health').textContent=result.exiting?'Exiting Safely':'Exit Failed';clearTimeout(state.timer);clearTimeout(state.rangeValidationTimer)}catch(error){button.disabled=false;button.textContent='Exit Optimizer';$('health').textContent=error.message;$('health').classList.add('bad')}}

$('maestroPath').value=localStorage.getItem('crescendo.adeSetupPath')||localStorage.getItem('crescendo.maestroPath')||'';
$('algorithm').onchange=renderAlgorithmSettings;Object.values(algorithmInputMaps).flatMap(map=>Object.values(map)).forEach(id=>{$(id).oninput=()=>{$(id).dataset.manual='true';renderAlgorithmSettings()}});$('resetAlgorithmDefaults').onclick=()=>updateAlgorithmDefaults(true);updateAlgorithmDefaults(true);
$('saveEdaSetup').onclick=saveEdaSetup;$('resetEdaSetup').onclick=resetEdaSetup;$('edaPdkPolicy').onchange=togglePdkCustomAdapter;
$('maestroPath').oninput=()=>{++state.loadToken;resetPrepared();state.testInspectionId=null;$('testSelect').disabled=true;$('inspectCellsButton').disabled=true};$('loadButton').onclick=loadSetup;$('testSelect').onchange=()=>{++state.loadToken;resetPrepared();$('inspectCellsButton').disabled=!$('testSelect').value};$('inspectCellsButton').onclick=inspectSelectedTest;$('applyCellsButton').onclick=applyCells;$('nativeBrowseButton').onclick=nativeBrowse;$('browseButton').onclick=openBrowser;$('saveConfigButton').onclick=saveDesignConfig;$('loadConfigButton').onclick=()=>$('configFileInput').click();$('configFileInput').onchange=loadDesignConfigFile;$('closeBrowser').onclick=closeBrowser;$('browserUp').onclick=()=>browse($('browserUp').dataset.path);$('useCurrent').onclick=()=>selectAdeSetup(state.browsePath);$('browserModal').onclick=event=>{if(event.target===$('browserModal'))closeBrowser()};
$('runButton').onclick=startRun;$('stopButton').onclick=stopRun;$('validateRangesButton').onclick=validateAllRanges;$('applyValidatedRangesButton').onclick=applyValidatedRanges;$('addObjective').onclick=addObjective;$('addConstraint').onclick=addConstraint;$('parameterFilter').oninput=renderParameters;document.querySelectorAll('[data-semantic]').forEach(button=>button.onclick=()=>{selectSemantic(button.dataset.semantic,button.dataset.selected==='true');flashSemanticButton(button)});$('expandParameterTree').onclick=()=>setParameterTreeExpanded(true);$('collapseParameterTree').onclick=()=>setParameterTreeExpanded(false);$('tradeoffX').onchange=()=>renderTradeoff(state.liveCandidates,state.liveSpec);$('tradeoffY').onchange=()=>renderTradeoff(state.liveCandidates,state.liveSpec);
$('saveCheckpointButton').onclick=saveCheckpoint;$('loadCheckpointButton').onclick=loadOrResumeCheckpoint;$('checkpointFileInput').onchange=loadCheckpointFile;$('refreshRecentRuns').onclick=loadRecentRuns;
$('exportCsvButton').onclick=exportCandidatesCsv;
$('exitOptimizerButton').onclick=exitOptimizer;
api('/api/health').then(()=>{$('health').textContent='Service Online';loadEdaSetup();loadRecentRuns()}).catch(()=>{$('health').textContent='Connection Failed';$('health').classList.add('bad')});
